// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;
// 只声明我们要用的三个函数。Escrow 通过这个接口去调用任何 ERC20 合约。
interface IERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns
    (bool);
    function balanceOf(address account) external view returns (uint256);
    }
    contract Escrow {
    // ---------- 状态机 ----------
    enum Status { Created, Paid, Completed, Refunded, Disputed }
    struct Order {
    address buyer;
    address seller;
    address token; // 用哪种 ERC20 结算
    uint256 amount; // 最小单位
    uint256 deadline; // unix 时间戳，秒
    Status status;
    string description;
    }
    // ---------- 存储 ----------
    address public arbiter;
    uint256 public orderCount;
    mapping(uint256 => Order) private _orders;
    // ---------- 事件 ----------
    event OrderCreated(uint256 indexed id, address indexed buyer, address indexed
    seller, address token, uint256 amount, uint256 deadline);
    event OrderPaid(uint256 indexed id);
    event OrderCompleted(uint256 indexed id);
    event OrderRefunded(uint256 indexed id);
    event OrderDisputed(uint256 indexed id, address by);
    event OrderResolved(uint256 indexed id, bool sellerWins);
    // ---------- 修饰器 ----------
    modifier onlyArbiter() {
    require(msg.sender == arbiter, "Escrow: caller is not the arbiter");
    _;
    }
    modifier onlyBuyer(uint256 id) {
    require(msg.sender == _orders[id].buyer, "Escrow: caller is not the buyer");
    _;
    }
    modifier inStatus(uint256 id, Status s) {
    require(_orders[id].status == s, "Escrow: wrong status");
    _;
    }
    constructor(address _arbiter) {
    require(_arbiter != address(0), "Escrow: arbiter is the zero address");
    arbiter = _arbiter;
    }
    function getOrder(uint256 id) public view returns (Order memory) {
    require(id < orderCount, "Escrow: order does not exist");
    return _orders[id];
    }

    // ---------- TODO 1：创建订单 ----------
    function createOrder(address seller, address token, uint256 amount, uint256 deadline, string memory description) public returns (uint256) {
        require(seller != address(0), "Escrow: seller is the zero address");
        require(seller != msg.sender, "Escrow: seller is the buyer");
        require(amount > 0, "Escrow: amount must be positive");
        require(deadline > block.timestamp, "Escrow: deadline must be in the future");

        uint256 id = orderCount;
        _orders[id] = Order({
            buyer: msg.sender,
            seller: seller,
            token: token,
            amount: amount,
            deadline: deadline,
            status: Status.Created,
            description: description
        });
        orderCount += 1;

        emit OrderCreated(id, msg.sender, seller, token, amount, deadline);
        return id;
    }

    // ---------- TODO 2：买家付款 ----------
    // 修饰器已修正为 inStatus(id, Status.Created)
    function deposit(uint256 id) public onlyBuyer(id) inStatus(id, Status.Created) {
        Order storage o = _orders[id];

        // 先改状态，再外部调用
        o.status = Status.Paid;

        // 代币合约看到的 msg.sender 是 Escrow 合约本身，
        // 所以买家必须事先对 Escrow 合约地址 approve 过额度。
        bool ok = IERC20(o.token).transferFrom(o.buyer, address(this), o.amount);
        require(ok, "Escrow: transferFrom failed");

        emit OrderPaid(id);
    }

    // ---------- TODO 3：买家确认收货 ----------
    function confirm(uint256 id) public onlyBuyer(id) inStatus(id, Status.Paid) {
        Order storage o = _orders[id];

        o.status = Status.Completed;

        bool ok = IERC20(o.token).transfer(o.seller, o.amount);
        require(ok, "Escrow: transfer failed");

        emit OrderCompleted(id);
    }

    // ---------- TODO 4：超期退款 ----------
    function refund(uint256 id) public onlyBuyer(id) inStatus(id, Status.Paid) {
        Order storage o = _orders[id];
        require(block.timestamp > o.deadline, "Escrow: deadline not reached");

        o.status = Status.Refunded;

        bool ok = IERC20(o.token).transfer(o.buyer, o.amount);
        require(ok, "Escrow: transfer failed");

        emit OrderRefunded(id);
    }

    // ---------- TODO 5：发起争议 ----------
    function dispute(uint256 id) public inStatus(id, Status.Paid) {
        Order storage o = _orders[id];
        require(
            msg.sender == o.buyer || msg.sender == o.seller,
            "Escrow: caller is not buyer or seller"
        );

        o.status = Status.Disputed;

        emit OrderDisputed(id, msg.sender);
    }

    // ---------- TODO 6：仲裁 ----------
    function resolve(uint256 id, bool sellerWins) public onlyArbiter inStatus(id, Status.Disputed) {
        Order storage o = _orders[id];

        address to;
        if (sellerWins) {
            o.status = Status.Completed;
            to = o.seller;
        } else {
            o.status = Status.Refunded;
            to = o.buyer;
        }

        bool ok = IERC20(o.token).transfer(to, o.amount);
        require(ok, "Escrow: transfer failed");

        emit OrderResolved(id, sellerWins);
    }
}

contracts/ZRAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;
contract ZRAToken {
    // ---------- 元数据 ----------
    string public name = "ZRAToken";
    string public symbol = "ZRA202430552905";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    // ---------- 权限 ----------
    address public owner;
    modifier onlyOwner() {
        require(msg.sender == owner, "ZRAToken: caller is not the owner");
        _;
    }
    // ---------- 状态 ----------
    // 这两个 mapping 就是"账本"。代币不存在于任何钱包里，只存在于这里。
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    // ---------- 事件 ----------
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    constructor() {
        owner = msg.sender;
    }
    // ---------- 只读查询 ----------
    function balanceOf(address account) public view returns (uint256) {
        return _balances[account];
    }
    function allowance(address _owner, address spender) public view returns (uint256) {
        return _allowances[_owner][spender];
    }
    // ---------- TODO 1：转账 ----------
    function transfer(address to, uint256 value) public returns (bool) {
        require(to != address(0), "ZRAToken: transfer to zero address");
        require(_balances[msg.sender] >= value, "ZRAToken: insufficient balance");

        _balances[msg.sender] -= value;
        _balances[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }
    // ---------- TODO 2：授权 ----------
    function approve(address spender, uint256 value) public returns (bool) {
        _allowances[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }
    // ---------- TODO 3：代扣转账 ----------
    function transferFrom(address from, address to, uint256 value) public returns (bool) {
        require(to != address(0), "ZRAToken: transfer to zero address");
        require(_balances[from] >= value, "ZRAToken: insufficient balance");
        require(_allowances[from][msg.sender] >= value, "ZRAToken: insufficient allowance");

        _allowances[from][msg.sender] -= value;
        _balances[from] -= value;
        _balances[to] += value;
        emit Transfer(from, to, value);
        return true;
    }
    // ---------- TODO 4：增发（只有 owner 能调） ----------
    function mint(address to, uint256 value) public onlyOwner {
        require(to != address(0), "ZRAToken: mint to zero address");

        totalSupply += value;
        _balances[to] += value;
        emit Transfer(address(0), to, value);
    }
    // ---------- TODO 5：销毁自己的代币 ----------
    function burn(uint256 value) public {
        require(_balances[msg.sender] >= value, "ZRAToken: burn exceeds balance");

        _balances[msg.sender] -= value;
        totalSupply -= value;
        emit Transfer(msg.sender, address(0), value);
    }
}
